package app.gtdial.lab;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.json.*;
final class DialRepository {
 static final int MAX=100; static final class Dial{final String id,name;final File image;final int position,color;final JSONArray placements;Dial(String i,String n,File f,int p,int c,JSONArray a){id=i;name=n;image=f;position=p;color=c;placements=a;}boolean uploadable(){return placements.length()==0;}}
 private final File root; DialRepository(Context c){root=new File(c.getFilesDir(),"dials");}
 List<Dial> list(){ArrayList<Dial> out=new ArrayList<>();File[] ds=root.listFiles(File::isDirectory);if(ds==null)return out;for(File d:ds)try{UUID.fromString(d.getName());File f=new File(d,"background.png"),mf=new File(d,"metadata.json");if(!f.isFile()||!mf.isFile())continue;JSONObject m=new JSONObject(read(mf));if(m.optInt("schemaVersion")!=1||!d.getName().equals(m.optString("id")))continue;JSONArray a=m.optJSONArray("draftPlacements");out.add(new Dial(d.getName(),m.getString("name"),f,m.optInt("positionIndex",1),m.optInt("colorArgb",0xffffffff),a==null?new JSONArray():a));}catch(Exception ignored){}out.sort((a,b)->Long.compare(b.image.lastModified(),a.image.lastModified()));return out;}
 void save(String id,byte[] png,String name,int position,int color,JSONArray placements)throws Exception{UUID.fromString(id);if(png==null||png.length==0||name==null||name.trim().isEmpty()||name.length()>80)throw new IllegalArgumentException("dial metadata");boolean exists=image(id).isFile();if(!exists&&list().size()>=MAX)throw new IOException("Галерея заполнена");File d=image(id).getParentFile();if(!d.exists()&&!d.mkdirs())throw new IOException("mkdir");long now=System.currentTimeMillis(),created=now;File mf=new File(d,"metadata.json");if(mf.isFile())try{created=new JSONObject(read(mf)).optLong("createdAt",now);}catch(Exception ignored){}write(new File(d,"background.png"),png);JSONObject m=new JSONObject().put("schemaVersion",1).put("id",id).put("name",name.trim()).put("createdAt",created).put("updatedAt",now).put("sha256",hash(png)).put("positionIndex",position).put("colorArgb",color).put("draftPlacements",placements==null?new JSONArray():placements);write(mf,m.toString().getBytes(StandardCharsets.UTF_8));}
 void delete(String id)throws IOException{File d=image(id).getParentFile();File[] fs=d.listFiles();if(fs!=null)for(File f:fs)if(!f.delete())throw new IOException("delete "+f.getName());if(d.exists()&&!d.delete())throw new IOException("delete dial");}
 private File image(String id){try{UUID.fromString(id);}catch(Exception e){throw new IllegalArgumentException("id");}File d=new File(root,id);try{if(!d.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IllegalArgumentException("path");}catch(IOException e){throw new IllegalArgumentException(e);}return new File(d,"background.png");}
 private static void write(File f,byte[] b)throws IOException{AtomicFile a=new AtomicFile(f);FileOutputStream o=null;try{o=a.startWrite();o.write(b);o.getFD().sync();a.finishWrite(o);}catch(IOException e){if(o!=null)a.failWrite(o);throw e;}}
 private static String read(File f)throws IOException{try(FileInputStream i=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[4096];for(int n;(n=i.read(b))!=-1;)o.write(b,0,n);return o.toString("UTF-8");}}
 private static String hash(byte[] b)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte x:h)s.append(String.format(Locale.US,"%02x",x));return s.toString();}
}
